// Restrict formats to what you actually scan — faster detection + fewer misclassifications.
final ctrl = MobileScannerController(
  formats: const [
    BarcodeFormat.ean13,       // retail POS
    BarcodeFormat.code128,     // logistics
    BarcodeFormat.dataMatrix,  // pharma
    BarcodeFormat.qrCode,      // consumer + payments
  ],
);

// Handle detection generically:
void onDetect(BarcodeCapture cap) {
  for (final b in cap.barcodes) {
    switch (b.format) {
      case BarcodeFormat.ean13:
      case BarcodeFormat.ean8:
      case BarcodeFormat.upcA:
      case BarcodeFormat.upcE:
        _handleRetail(b.rawValue!);
        break;
      case BarcodeFormat.code128:
        _handleLogistics(b.rawValue!);   // possibly GS1-128 with AIs
        break;
      case BarcodeFormat.dataMatrix:
        _handlePharma(b.rawValue!);
        break;
      case BarcodeFormat.qrCode:
        _handleQr(b.rawValue!);
        break;
      default:
    }
  }
}
